// Types of drafftink-canvas.
//
// The shape model below mirrors drafftink-scene (docs/model.md): the same field names and values as the document
// file, so `stage.get(id)` returns what `toJSON()` holds. `ShapeInit` adds a flat shorthand for writing shapes.
// The low-level wasm class is typed in dist/drafftink_canvas_js.d.ts (generated by wasm-bindgen) and exported as
// `RawStage`.

export { Stage as RawStage } from "../dist/drafftink_canvas_js";

// ---- the shape model ---------------------------------------------------------------------------------------

/** `#rrggbb`, or `#rrggbbaa` when not opaque. */
export type Color = string;
/** `[x, y]`. */
export type Point = [number, number];

export type StrokeStyle = "solid" | "dashed" | "dotted";
export type FillPattern = "solid" | "hachure" | "zigzag" | "cross_hatch" | "dots" | "dashed" | "zigzag_line";
/** How hand-drawn the lines are: `architect` is precise, `drunk` is wild. */
export type Sloppiness = "architect" | "artist" | "cartoonist" | "drunk";

export interface Style {
  stroke_color: Color;
  stroke_width: number;
  stroke_style: StrokeStyle;
  fill_color?: Color;
  fill_pattern: FillPattern;
  sloppiness: Sloppiness;
  /** 0 to 1. */
  opacity: number;
  corner_radius: number;
  /** Seed of the hand-drawn jitter; a new shape gets its own. */
  seed: number;
}

export type FontFamily = "gelpen" | "noto_sans" | "gelpen_serif" | "vanilla_extract" | "plex_sans";
export interface TextStyle {
  family: FontFamily;
  size: number;
  weight: "light" | "regular" | "heavy";
  align: "left" | "center" | "right";
  vertical_align: "top" | "middle" | "bottom";
  /** A multiple of the size. */
  line_height: number;
}

/** Position, size and rotation. The box is unrotated; `angle` turns it about its centre. */
export interface Transform {
  x: number;
  y: number;
  w: number;
  h: number;
  /** Radians, clockwise. */
  angle?: number;
  flip_x?: boolean;
  flip_y?: boolean;
}

export type Head =
  | "none" | "arrow" | "bar" | "circle" | "circle_outline" | "triangle" | "triangle_outline" | "diamond" | "diamond_outline"
  | "cardinality_one" | "cardinality_many" | "cardinality_one_or_many" | "cardinality_exactly_one"
  | "cardinality_zero_or_one" | "cardinality_zero_or_many";

export interface Binding {
  target: string;
  mode: "inside" | "orbit";
  fixed_point: Point;
}

export interface LinearData {
  /** Relative to the top-left corner of the box. */
  points: Point[];
  path?: "sharp" | "round" | "elbow";
  start_binding?: Binding;
  end_binding?: Binding;
  start_head?: Head;
  end_head?: Head;
  head_size?: number;
  closed?: boolean;
}

export interface FreehandData {
  points: Point[];
  pressures?: number[];
  pressure_mode?: "uniform" | "simulated" | "device";
  brush?: "normal" | "calligraphy";
  highlighter?: boolean;
  closed?: boolean;
}

export interface TextData {
  content: string;
  /** Colours of ranges of characters. */
  runs?: { start: number; end: number; color?: Color }[];
  font?: Partial<TextStyle>;
  /** `true` (default): the box follows the text. `false`: the text wraps at the width of the box. */
  auto_resize?: boolean;
  container_id?: string;
  label_position?: number;
}

export type Kind =
  | { type: "rectangle" }
  | { type: "diamond" }
  | { type: "ellipse" }
  | ({ type: "line" } & LinearData)
  | ({ type: "arrow" } & LinearData)
  | ({ type: "freehand" } & FreehandData)
  | ({ type: "text" } & TextData)
  | { type: "math"; latex: string; font_size?: number }
  | { type: "image"; file_id?: string; natural_width: number; natural_height: number; crop?: { x: number; y: number; width: number; height: number } }
  | { type: "frame"; name?: string; clip?: boolean };

export type ShapeType = Kind["type"];

/** A shape as the stage stores and returns it. */
export interface Shape {
  id: string;
  kind: Kind;
  transform: Transform;
  style: Style;
  /** The z-order key; it sorts bottom to top. */
  index: string;
  /** The groups the shape is in, innermost first. */
  group_ids?: string[];
  frame_id?: string;
  locked?: boolean;
  deleted?: boolean;
  /** Words separated by spaces, like CSS classes: `.card` selects `"card big"`. */
  name?: string;
  link?: string;
  /** Your data. `{ draggable: false }` keeps the shape in place when the built-in drag is on. */
  custom?: Record<string, unknown>;
  version?: number;
}

/**
 * A shape for `add`. Either the full layout, or the flat shorthand: `x`, `y`, `w`, `h`, `angle` at the top
 * level go to `transform`, and `type` with the fields of the kind (`points`, `content`, ...) go to `kind`.
 * Points of lines, arrows and strokes are relative to `x`, `y`.
 */
export type ShapeInit = {
  id?: string;
  style?: Partial<Style>;
  group_ids?: string[];
  frame_id?: string;
  locked?: boolean;
  name?: string;
  link?: string;
  custom?: Record<string, unknown>;
  transform?: Partial<Transform>;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  angle?: number;
} & (
  | { type: "rectangle" | "diamond" | "ellipse" }
  | ({ type: "line" | "arrow" } & Partial<LinearData> & { points: Point[] })
  | ({ type: "freehand" } & FreehandData)
  | ({ type: "text" } & TextData)
  | { type: "math"; latex: string; font_size?: number }
  | { type: "frame"; clip?: boolean }
  | { type: "image"; file_id: string; natural_width: number; natural_height: number }
);

/** A merge patch (RFC 7396): objects merge field by field, `null` removes a field, anything else replaces. */
export type ShapePatch = {
  style?: { [K in keyof Style]?: Style[K] | null };
  transform?: Partial<Transform>;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  angle?: number;
  name?: string | null;
  link?: string | null;
  locked?: boolean;
  custom?: Record<string, unknown> | null;
  /** Fields of the shape's kind: `points`, `content`, `latex`, ... */
  [kindField: string]: unknown;
};

/** The native document: what `toJSON()` returns and `load` accepts. */
export interface Document {
  format: "drafftink";
  version: number;
  name: string;
  background: Color;
  elements: Shape[];
  files?: Record<string, { mime: string; data: string }>;
}

// ---- results ---------------------------------------------------------------------------------------------

export interface Hit {
  id: string;
  part: "stroke" | "fill" | "body";
}

export interface Camera {
  /** The world point at the centre of the canvas. */
  scroll: Point;
  /** Pixels per world unit, 0.1 to 30. */
  zoom: number;
}

export interface Modifiers {
  shift: boolean;
  ctrl: boolean;
  alt: boolean;
  meta: boolean;
}

/** A handle of the transformer. */
export type Handle =
  | "TopLeft" | "Top" | "TopRight" | "Right" | "BottomRight" | "Bottom" | "BottomLeft" | "Left" | "Rotate"
  | { Point: { element: string; index: number } }
  | { Midpoint: { element: string; segment: number } };

export type EventName =
  | "pointerdown" | "click" | "dblclick" | "longpress" | "contextmenu" | "dragstart" | "dragmove" | "dragend"
  | "pointerenter" | "pointerleave" | "transformstart" | "transform" | "transformend";

/** What a listener receives. */
export interface StageEvent {
  type: EventName;
  /** The shape the event is about; `null` for empty space and for handles. */
  target: string | null;
  /** The node whose listener runs now. */
  currentTarget: { kind: "element" | "group"; id: string } | { kind: "stage" };
  /** Pointer position in pixels on the canvas. */
  screen: Point;
  /** Pointer position in world units. */
  world: Point;
  /** Movement since the press, in pixels (drag events). */
  deltaScreen: Point;
  /** Movement since the press, in world units. */
  deltaWorld: Point;
  modifiers: Modifiers;
  pointer: "mouse" | "pen" | "touch";
  button: "none" | "primary" | "secondary" | "middle" | "other";
  /** The handle of a `transform*` event. */
  handle: Handle | null;
  /** The pointer was on the link icon of `target`, not on the shape: open `shape.link` on a `click` with this set. */
  linkIcon: boolean;
  /** The drag was aborted (Escape, a second finger). */
  cancelled: boolean;
  /** Ends the bubble after the listeners of the current node have run. */
  stopPropagation(): void;
}

/** What the recognizer reports; see docs/canvas-api.md §3. */
export type Intent = Record<string, unknown>;

export interface Outline {
  id: string;
  /** SVG path data in world units. */
  path: string;
}

export interface Overlay {
  zoom: number;
  selection: { id?: string; corners: [Point, Point, Point, Point]; angle: number }[];
  transformer:
    | { frame: "box"; box: { corners: [Point, Point, Point, Point]; angle: number }; multi: boolean; handles: HandleInfo[]; active: Handle | null; handleSizePx: number }
    | { frame: "linear"; element: string; points: Point[]; closed: boolean; handles: HandleInfo[]; active: Handle | null; handleSizePx: number }
    | null;
  hover: Outline | null;
  /** `[x, y, w, h]`. */
  marquee: [number, number, number, number] | null;
  highlights: Outline[];
  cursors: { user: string; name: string | null; at: Point }[];
  /** What other people have selected. */
  remoteSelections: { user: string; color: Color; boxes: { corners: [Point, Point, Point, Point]; angle: number }[]; truncated: boolean }[];
  /** The link icons of the shapes in view that are not selected. */
  linkIcons: { shape: string; /** `[x, y, w, h]` */ rect: [number, number, number, number]; toShape: boolean }[];
}

/** A person in the room (`stage.setRemoteUsers`). */
export interface RemoteUser {
  id: string;
  /** Shown in a label beside the pointer. */
  name?: string;
  color: Color;
  /** The pointer in world units; leave out when it is outside the canvas. */
  cursor?: [number, number];
  /** Ids of the shapes they have selected (unknown ids are skipped). */
  selection?: string[];
  /** The recent path of the pointer, oldest first. */
  trail?: { x: number; y: number; ageMs: number }[];
}

/** Where and how big `stage.addImage` puts a picture. */
export interface ImageOptions {
  id?: string;
  x?: number;
  y?: number;
  /** With only a width the height follows the picture's proportions, and the other way round. */
  width?: number;
  height?: number;
  /** The longer side is at most this: a bigger picture is scaled down, a smaller one is left alone. */
  maxSide?: number;
  name?: string;
}

export interface HandleInfo {
  handle: Handle;
  at: Point;
  screen: Point;
}

// ---- options ---------------------------------------------------------------------------------------------

export interface StageOptions {
  /** Size in CSS pixels. Default: the canvas's. */
  width?: number;
  height?: number;
  /** Device pixels per CSS pixel. Default: `window.devicePixelRatio`. */
  devicePixelRatio?: number;
  background?: Color;
  theme?: "light" | "dark";
  grid?: { kind?: "none" | "lines" | "rules" | "crosses" | "dots"; spacing?: number };
  /** Built-in pointer behaviour. Turn a part off to do it with your own listeners. */
  interaction?: {
    /** A press selects; a press on empty space clears. Default `true`. */
    select?: boolean;
    /** A drag moves the shape or the selection. Default `true`. */
    drag?: boolean;
    /** The handles of the transformer resize, rotate and reshape. Default `true`. */
    transform?: boolean;
    /** The rubber band on empty space. Default `"contain"`. */
    marquee?: "off" | "contain" | "intersect";
  };
  /** Style every added shape starts from, e.g. `{ sloppiness: "architect" }` for precise lines. */
  defaultStyle?: Partial<Style>;
  /** Hit tolerances, gesture thresholds and handle sizes (a partial `CanvasConfig`, docs/canvas-api.md). */
  config?: Record<string, unknown>;
  /** A document to start with. */
  document?: Document;
  // Options of the browser glue:
  /** Where the wasm file is: a URL, a `Response`, bytes or a module. Default: next to the package. */
  wasm?: string | URL | Response | BufferSource | WebAssembly.Module;
  /** Follow the canvas's CSS size and the device pixel ratio. Default `true`. */
  autoResize?: boolean;
  /** Listen for pointer, wheel and key events on the canvas. Default `true`. */
  interactive?: boolean;
  /** Set `canvas.style.cursor` from hover. Default `true`. */
  cursor?: boolean;
  /** When WebGPU is missing, replace the page with an explanation. Default `false`: the promise rejects. */
  errorPage?: boolean;
}

export interface SvgOptions {
  look?: "sketch" | "clean";
  background?: boolean;
  padding?: number;
  scale?: number;
  /** Only these shapes (and the text bound to them). */
  selection?: string[];
  /** Store the scene in the file so `load` can open it. Default `true`. */
  embedScene?: boolean;
}

export interface PngOptions {
  /** Pixels per world unit. Default 1. */
  scale?: number;
  padding?: number;
  /** `false` leaves the background transparent. */
  background?: boolean;
  selection?: string[];
  theme?: "light" | "dark";
  embedScene?: boolean;
}

/** A write inside `transact`. */
export interface Transaction {
  add(shape: ShapeInit): string;
  /** Adds a PNG, JPEG, WebP, GIF, BMP or ICO picture (from a `Blob`, `File`, `ArrayBuffer` or bytes) at its natural size. */
  addImage(source: Blob | ArrayBuffer | Uint8Array, options?: ImageOptions): Promise<string>;
  update(id: string, patch: ShapePatch): void;
  remove(...ids: (string | string[])[]): void;
  order(ids: string | string[], to: "front" | "back" | "forward" | "backward"): void;
  group(ids: string[], id?: string): string | undefined;
  ungroup(ids: string | string[]): void;
  lock(ids: string | string[], locked?: boolean): void;
  move(ids: string | string[], dx: number, dy: number): void;
}

// ---- the stage -------------------------------------------------------------------------------------------

export class Stage {
  /** Mounts a stage on a canvas. Rejects when the browser has no WebGPU. */
  static create(canvas: HTMLCanvasElement, options?: StageOptions): Promise<Stage>;

  add(shape: ShapeInit): string;
  update(id: string, patch: ShapePatch): void;
  remove(...ids: (string | string[])[]): void;
  clear(): void;
  /** One commit, or none when a step is refused. Returns what each step produced. */
  transact(fn: (tx: Transaction) => void): (string | null)[];
  order(ids: string | string[], to: "front" | "back" | "forward" | "backward"): void;
  group(ids: string[], id?: string): string;
  ungroup(ids: string | string[]): void;
  get(id: string): Shape;
  all(): Shape[];
  /** `#id`, `.name`, `rectangle`, `group:g1`, `*`. */
  find(selector: string): string[];
  readonly count: number;

  toJSON(): Document;
  exportJSON(pretty?: boolean): string;
  /** A document object or text, or the bytes of a file: JSON, a PNG or SVG made by `toPNG`/`toSVG`, `.excalidraw`, old drafft-ink JSON. */
  load(source: Document | string | Uint8Array): void;
  toSVG(options?: SvgOptions): string;
  toPNG(options?: PngOptions): Promise<Uint8Array>;

  camera: Camera;
  panBy(dx: number, dy: number): void;
  zoomAt(x: number, y: number, factor: number): void;
  fitToContent(options?: { padding?: number; maxZoom?: number; ids?: string[] }): void;
  worldToScreen(point: Point): Point;
  screenToWorld(point: Point): Point;
  resize(width: number, height: number, devicePixelRatio?: number): void;

  hit(x: number, y: number, options?: { tolerancePx?: number }): Hit | null;
  hitAll(x: number, y: number): Hit[];
  marquee(rect: { x: number; y: number; w: number; h: number }, mode?: "contain" | "intersect"): string[];
  inRect(rect: { x: number; y: number; w: number; h: number }): string[];
  pick(x: number, y: number): unknown;

  setSelection(ids: string[]): void;
  readonly selection: string[];
  setEnteredGroup(group: string | null): void;
  setPointerMode(mode: "select" | "hand" | "draw"): void;
  setHighlights(ids: string[]): void;
  /** Draws the people in the room: pointers with names, outlines of their selections, their laser trails. */
  setRemoteUsers(users: RemoteUser[]): void;
  overlay(): Overlay;

  setTheme(theme: "light" | "dark"): void;
  setGrid(grid: { kind?: "none" | "lines" | "rules" | "crosses" | "dots"; spacing?: number }): void;
  setBackground(color: Color): void;

  /** `selector` defaults to `"stage"`. Returns a handle for `off`. Listeners may change the stage; reads wait until they return. */
  on(event: EventName, selector: string, callback: (event: StageEvent) => void): number;
  on(event: EventName, callback: (event: StageEvent) => void): number;
  on(event: "selectionchange", callback: (selection: string[]) => void): number;
  on(event: "change", callback: () => void): number;
  on(event: "intent", callback: (intent: Intent) => void): number;
  off(handle: number): void;
  handleInput(event: unknown): Intent[];

  render(): boolean;
  stats(): {
    elements: number;
    framesDrawn: number;
    adapter: string | null;
    lost: string | null;
    lastFrame: { inView: number; culled: number; drawn: number; encoded: number; reused: number };
  };
  readonly framesDrawn: number;
  readonly canvas: HTMLCanvasElement;
  destroy(): void;
}

export function loadWasm(source?: StageOptions["wasm"]): Promise<unknown>;
export function webgpuAvailable(): boolean;
export function showErrorPage(title: string, details: string): void;
